send-one-way-request.set-body:
@{
                    var path = context.Request.OriginalUrl.Path ?? "";
                    var metricName = "{{aforo-default-metric}}";
                    foreach (var rule in "{{aforo-metric-mappings}}".Split(new[] { ";", "\n" }, StringSplitOptions.RemoveEmptyEntries)) {
                        var p = rule.Split(new[] { "|" }, StringSplitOptions.None);
                        if (p.Length != 3) { continue; }
                        var kind = p[0].Trim().ToUpperInvariant();
                        var value = p[1].Trim();
                        var metric = p[2].Trim();
                        if (value.Length == 0 || metric.Length == 0) { continue; }
                        if ((kind == "EXACT" && path == value)
                            || (kind == "PREFIX" && path.StartsWith(value))
                            || (kind == "CONTAINS" && path.Contains(value))) {
                            metricName = metric;
                            break;
                        }
                    }
                    var evt = new JObject(
                        new JProperty("events", new JArray(
                            new JObject(
                                new JProperty("customerId", context.Variables.GetValueOrDefault<string>("aforo-customer-id", "")),
                                new JProperty("metricName", metricName),
                                new JProperty("quantity", 1),
                                new JProperty("idempotencyKey", context.RequestId.ToString()),
                                new JProperty("occurredAt", DateTime.UtcNow.ToString("o")),
                                new JProperty("productType", context.Variables.GetValueOrDefault<string>("aforo-product-type", "API")),
                                new JProperty("endpointPath", path),
                                new JProperty("httpMethod", context.Request.Method),
                                new JProperty("statusCode", context.Response.StatusCode),
                                new JProperty("responseTimeMs", (int)context.Elapsed.TotalMilliseconds),
                                new JProperty("metadata", new JObject(
                                    new JProperty("gateway", "azure-apim"),
                                    new JProperty("product", context.Product != null ? context.Product.Id : ""),
                                    new JProperty("subscription", context.Subscription != null ? context.Subscription.Id : ""),
                                    new JProperty("operation", context.Operation != null ? context.Operation.Id : "")
                                ))
                            )
                        ))
                    );
                    return evt.ToString();
                }
